if(introCourse){introCourse.lessons.forEach(l=>{const hero=introExternalVisuals[l.title], after=introAfterVisuals[l.title]; if(hero){l.image=introExternalImageByTitle[l.title];l.visualCaption=hero[1];l.heroSource=introExternalSourceByTitle[l.title];} if(after){l.visuals=[{src:introAfterImageByTitle[l.title],caption:after[1],kind:after[2]||'photo',source:introAfterSourceByTitle[l.title]}];}});}
