// Knowledge-base deduplication: remove only confirmed semantic duplicates.
(function(){
  const removeIfPresent=[
    ["Толщина бумаги","Толщина материала"],
    ["Плашка 100%","Плашка"],
    ["Фольгирование","Тиснение фольгой"],
    ["CIELAB","L*a*b*"]
  ];
  const removed=[];
  removeIfPresent.forEach(([duplicate,canonical])=>{
    const hasCanonical=knowledgeArticles.some(a=>a[0]===canonical);
    if(!hasCanonical)return;
    for(let i=knowledgeArticles.length-1;i>=0;i--){
      if(knowledgeArticles[i][0]===duplicate){
        knowledgeArticles.splice(i,1);
        removed.push(duplicate);
      }
    }
  });
  const seen=new Set();
  for(let i=knowledgeArticles.length-1;i>=0;i--){
    const key=String(knowledgeArticles[i][0]||'').toLowerCase().replace(/ё/g,'е').replace(/[^a-zа-я0-9]+/gi,' ').trim();
    if(!key||seen.has(key)){
      removed.push(knowledgeArticles[i][0]);
      knowledgeArticles.splice(i,1);
    }else{
      seen.add(key);
    }
  }
  window.__knowledgeDedup={removed:removed.length,removedTitles:[...new Set(removed)]};
})();

