if(xl105Course){
 xl105Course.lessons.forEach(l=>{
   const p=XL105_PHOTO_BY_LESSON[l.title];
   if(!p)return;
   const current=Array.isArray(l.visuals)?l.visuals:[];
   const photoItem={src:p[0],caption:p[1],kind:'photo'};
   // Remove any previous photo with the same URL, then place the real photo first.
   const withoutSame=current.filter(v=>v.kind!=='photo' || v.src!==p[0]);
   l.visuals=[photoItem,...withoutSame];
 });
}

