function diagnosticTrainerState(id){
 const existing=state.diagnostics?.[id];
 if(existing&&typeof existing==='object')return existing;
 return {step:0,answers:[],score:0,completed:false,startedAt:new Date().toISOString(),completedAt:null};
}
function saveDiagnosticSession(id,session){if(!state.diagnostics)state.diagnostics={};state.diagnostics[id]=session;save();}
function diagnosticTrainerCase(id){return DIAGNOSTIC_TRAINER_CASES.find(x=>x.id===id)||DIAGNOSTIC_TRAINER_CASES[0];}
function startDiagnosticCase(index=0){if(!isAuthenticated()){openAuth('register');return;}const c=DIAGNOSTIC_TRAINER_CASES[Math.max(0,Math.min(index,DIAGNOSTIC_TRAINER_CASES.length-1))];if(!state.diagnostics[c.id]||state.diagnostics[c.id].completed){saveDiagnosticSession(c.id,{step:0,answers:[],score:0,completed:false,startedAt:new Date().toISOString(),completedAt:null});}location.hash=`#/diagnostics/trainer?case=${encodeURIComponent(c.id)}`;}
function resetDiagnosticCase(id){if(!isAuthenticated()){openAuth('register');return;}const c=diagnosticTrainerCase(id);saveDiagnosticSession(c.id,{step:0,answers:[],score:0,completed:false,startedAt:new Date().toISOString(),completedAt:null});location.hash=`#/diagnostics/trainer?case=${encodeURIComponent(c.id)}`;}
function diagnosticTrainerAction(id,step,choice){if(!isAuthenticated()){openAuth('register');return;}const c=diagnosticTrainerCase(id);const session=diagnosticTrainerState(c.id);if(session.completed)return;const q=c.steps[step];if(!q)return;const selected=Number(choice);const correct=selected===q.correct;session.answers=Array.isArray(session.answers)?session.answers:[];session.answers[step]={choice:selected,correct};session.lastChoice=selected;session.lastCorrect=correct;session.lastExplanation=q.why;session.score=session.answers.filter(a=>a&&a.correct).length;saveDiagnosticSession(c.id,session);render();}
function diagnosticTrainerNext(id){if(!isAuthenticated()){openAuth('register');return;}const c=diagnosticTrainerCase(id);const session=diagnosticTrainerState(c.id);const step=Number(session.step||0);const answer=session.answers?.[step];if(!answer)return;if(!answer.correct){session.lastChoice=null;session.lastCorrect=null;session.lastExplanation='Попробуйте ещё раз. В тренажёре важно не угадать, а понять, какой признак ведёт к следующей проверке.';saveDiagnosticSession(c.id,session);render();return;}if(step>=c.steps.length-1){session.completed=true;session.completedAt=new Date().toISOString();session.lastChoice=null;session.lastCorrect=null;session.lastExplanation='Сценарий завершён. Результат сохранён в вашем браузере.';saveDiagnosticSession(c.id,session);render();return;}session.step=step+1;session.lastChoice=null;session.lastCorrect=null;session.lastExplanation='';saveDiagnosticSession(c.id,session);render();}
function diagnosticsTrainerPage(){
 if(!isAuthenticated())return diagnosticsAccessPage('trainer');
 const q=new URLSearchParams(location.hash.split('?')[1]||'');
 const id=q.get('case');
 if(!id)return diagnosticsTrainerHome();
 const c=diagnosticTrainerCase(id);const session=diagnosticTrainerState(c.id);const step=Math.min(Number(session.step||0),c.steps.length-1);const current=c.steps[step];const answer=session.answers?.[step];
 const completedCount=Object.values(state.diagnostics||{}).filter(x=>x&&x.completed).length;
 if(session.completed)return `<main class="section diagnostic-trainer"><div class="container"><a class="btn btn-ghost" href="#/diagnostics">← Диагностика</a><section class="trainer-result card"><div class="eyebrow">СЦЕНАРИЙ ЗАВЕРШЁН</div><div class="trainer-result-icon">✓</div><h1>${esc(c.title)}</h1><p class="lead">Вы прошли полный цикл: наблюдение → повторяемость → гипотеза → проверка → действие.</p><div class="trainer-score"><b>${session.score} / ${c.steps.length}</b><span>правильных решений</span></div><div class="trainer-result-grid"><div><strong>Что отработано</strong><p>Вы не просто выбрали ответ, а прошли последовательность диагностического мышления.</p></div><div><strong>Следующий шаг</strong><p>Повторите сценарий с другой логикой или откройте соответствующую карточку дефекта.</p></div></div><div class="hero-actions"><button class="btn btn-primary" onclick="resetDiagnosticCase('${c.id}')">Пройти ещё раз</button><a class="btn btn-ghost" href="#/defect/${c.defectIndex}">Открыть алгоритм дефекта →</a><a class="btn btn-ghost" href="#/diagnostics/trainer">Другой сценарий</a></div></section></div></main>`;
 const pct=Math.round((step/c.steps.length)*100);const correct=answer?.correct===true;const answered=!!answer;
 return `<main class="section diagnostic-trainer"><div class="container"><a class="btn btn-ghost" href="#/diagnostics/trainer">← Все сценарии</a><section class="trainer-header card"><div><span class="tag">ТРЕНАЖЁР · ${esc(c.category)}</span><h1>${esc(c.title)}</h1><p class="lead">${esc(c.summary)}</p></div><div class="trainer-meta"><span>${esc(c.difficulty)}</span><b>${completedCount} / ${DIAGNOSTIC_TRAINER_CASES.length}</b><small>сценариев пройдено</small></div></section><div class="trainer-progress"><div><span>Шаг ${step+1} из ${c.steps.length}</span><b>${esc(current.label)}</b></div><div class="progress"><i style="width:${Math.max(8,Math.round(((step+(answered?1:0))/c.steps.length)*100))}%"></i></div></div><section class="trainer-layout"><article class="card trainer-question"><div class="eyebrow">${String(step+1).padStart(2,'0')} · ${esc(current.label.toUpperCase())}</div><h2>${esc(current.question)}</h2><div class="trainer-options">${current.options.map((o,i)=>{const selected=answer?.choice===i;const cls=answered?(selected?(correct?'is-correct':'is-wrong'):''):' ';return `<button type="button" class="trainer-option ${cls}" ${answered&&correct?'disabled':''} onclick="diagnosticTrainerAction('${c.id}',${step},${i})"><span>${String.fromCharCode(65+i)}</span><strong>${esc(o)}</strong>${selected?`<em>${correct?'Ваш ответ':'Попытка'}</em>`:''}</button>`}).join('')}</div>${answered?`<div class="trainer-feedback ${correct?'is-correct':'is-wrong'}"><strong>${correct?'Верно':'Не совсем'}</strong><p>${esc(session.lastExplanation||current.why)}</p>${!correct?'<small>Выберите другой вариант, чтобы продолжить.</small>':''}</div>`:''}${answered&&correct?`<button class="btn btn-primary trainer-next" type="button" onclick="diagnosticTrainerNext('${c.id}')">${step===c.steps.length-1?'Завершить сценарий':'Следующий шаг'} →</button>`:''}</article><aside class="card trainer-side"><div class="eyebrow">ЛОГИКА</div><div class="trainer-chain">${c.steps.map((x,i)=>`<div class="trainer-chain-step ${i<step?'done':''} ${i===step?'current':''}"><b>${String(i+1).padStart(2,'0')}</b><span>${esc(x.label)}</span></div>`).join('')}</div><div class="notice"><b>Правило:</b> сначала фиксируем факт, затем строим гипотезу и только после этого выбираем проверку.</div></aside></section></div></main>`;
}
function diagnosticsTrainerHome(){
 if(!isAuthenticated())return diagnosticsAccessPage('trainer');
 const completed=Object.values(state.diagnostics||{}).filter(x=>x&&x.completed).length;
 return `<main class="section diagnostic-trainer"><div class="container"><div class="trainer-landing card"><div><div class="eyebrow">DIAGNOSTIC TRAINER · V100</div><h1>Тренажёр диагностики</h1><p class="lead">Не угадывайте причину дефекта. Пройдите рабочую последовательность: <b>симптом → наблюдение → повторяемость → гипотеза → проверка → действие</b>.</p><div class="hero-actions"><a class="btn btn-primary" href="#/diagnostics">Открыть справочник дефектов →</a></div></div><div class="trainer-landing-stat"><b>${completed}</b><span>из ${DIAGNOSTIC_TRAINER_CASES.length} сценариев пройдено</span></div></div><div class="section-head" style="margin-top:38px"><div><div class="eyebrow">СЦЕНАРИИ</div><h2>Выберите производственную ситуацию</h2><p class="section-intro">Каждый сценарий сохраняет результат локально. Ошибочный ответ не блокирует обучение: система объясняет логику и позволяет попробовать снова.</p></div></div><div class="grid grid-3 trainer-case-grid">${DIAGNOSTIC_TRAINER_CASES.map((c,i)=>{const s=state.diagnostics?.[c.id];const done=s?.completed;const score=s?.score||0;return `<article class="card trainer-case-card"><span class="tag">${esc(c.category)}</span><h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p><div class="trainer-case-meta"><span>${esc(c.difficulty)}</span><span>${done?'Пройден · '+score+'/'+c.steps.length:'5 шагов'}</span></div><button class="btn btn-primary" type="button" onclick="startDiagnosticCase(${i})">${done?'Пройти снова':'Начать сценарий'} →</button><a class="small" href="#/defect/${c.defectIndex}">Сначала открыть справочный алгоритм</a></article>`}).join('')}</div><div class="notice" style="margin-top:22px"><b>Важно:</b> тренажёр учит диагностическому мышлению. Конкретные настройки, допуски и действия всегда сверяются с документацией машины и локальной технологией.</div></div></main>`;
}
function diagnosticsAccessPage(kind='diagnostics'){
 const trainer=kind==='trainer';
 return `<main class="section diagnostic-access-page"><div class="container"><section class="card diagnostic-access-card"><div class="diagnostic-access-icon">⌁</div><div class="eyebrow">${trainer?'DIAGNOSTIC TRAINER':'DIAGNOSTICS'}</div><h1>${trainer?'Тренажёр диагностики':'Диагностика дефектов'}</h1><p class="lead">Этот раздел доступен зарегистрированным пользователям PrintStyle Academy.</p><div class="diagnostic-access-grid"><div><strong>Что будет доступно</strong><ul><li>26 справочных диагностических материалов;</li><li>пошаговые алгоритмы поиска причины;</li><li>интерактивный тренажёр производственных ситуаций;</li><li>сохранение результатов и прогресса в вашем профиле.</li></ul></div><div class="diagnostic-access-note"><span class="tag">ПОСЛЕ РЕГИСТРАЦИИ</span><p>Регистрация бесплатна и занимает меньше минуты. После входа раздел откроется автоматически.</p></div></div><div class="hero-actions"><button class="btn btn-primary" type="button" onclick="openAuth('register')">Зарегистрироваться →</button><button class="btn btn-ghost" type="button" onclick="openAuth('login')">Уже есть аккаунт · Войти</button></div></section></div></main>`;
}
function diagnosticsPage(){
 if(!isAuthenticated())return diagnosticsAccessPage('diagnostics');
 const groups=[['Все',''],['Цвет и краска','цвет краска плотность эмульгирование'],['Приводка и геометрия','приводка несовмещение деформация растискивание'],['Полосы и поверхность','полосы полошение царапины загрязнение'],['Материал и механика','бумага механика повреждения'],['Увлажнение','увлажнение вода']];
 return `<main class="section diagnostics-page"><div class="container"><div class="diagnostics-hero card"><div><div class="eyebrow">PRODUCTION DIAGNOSTICS · 26 КАРТОЧЕК</div><h1>Увидели дефект — разберитесь, где искать причину</h1><p class="lead">Ищите по названию или признаку. Каждая карточка помогает пройти путь от наблюдаемого симптома к проверке причины и контролю результата.</p></div><div class="diagnostic-steps"><span><b>01</b> Наблюдение</span><span><b>02</b> Повторяемость</span><span><b>03</b> Гипотеза</span><span><b>04</b> Проверка</span></div></div><div class="diagnostic-tools"><div class="search"><input class="input" id="defectSearch" aria-label="Поиск дефекта" placeholder="Например: полосы, цвет плывёт, приводка…" oninput="filterDefects(this.value)"><button class="btn btn-ghost" onclick="clearDefectSearch()">Сбросить</button></div><div class="defect-filters" id="defectFilters">${groups.map((g,i)=>`<button class="kb-chip ${i===0?'active':''}" data-filter="${esc(g[1])}" onclick="setDefectFilter('${esc(g[1]).replace(/'/g,"\'")}')">${esc(g[0])}</button>`).join('')}</div></div><div class="diagnostic-trainer-cta card"><div><div class="eyebrow">ПРАКТИКА</div><h2>Не только прочитать — пройти диагностику</h2><p>Тренажёр даёт производственную ситуацию и заставляет пройти её по шагам: наблюдение → гипотеза → проверка → действие.</p></div><a class="btn btn-primary" href="#/diagnostics/trainer">Запустить тренажёр →</a></div><div class="diagnostic-note"><b>Важно:</b> карточки помогают сформировать гипотезу. Конкретные настройки, допуски и действия определяются технологией, документацией машины и локальными инструкциями производства.</div><div class="kb-resultbar"><span id="defectResultCount">Показано ${defectLibrary.length} из ${defectLibrary.length}</span><span>26 диагностических карточек</span></div><div class="grid grid-3 defect-grid-v4" id="defectGrid">${defectLibrary.map((d,i)=>defectCardHtml(d,i)).join('')}</div></div></main>`
}
function filterDefects(q){
 const term=(q||document.getElementById('defectSearch')?.value||'').toLowerCase().trim(); const f=window.__defectFilter||'';
 const list=defectLibrary.map((d,i)=>({d,i})).filter(x=>(!f||defectSearchText(x.d).includes(f))&&(!term||defectSearchText(x.d).includes(term)));
 const grid=document.getElementById('defectGrid'); if(grid)grid.innerHTML=list.length?list.map(x=>defectCardHtml(x.d,x.i)).join(''):`<div class="card kb-empty"><div class="iconbox">?</div><h3>Дефект не найден</h3><p>Попробуйте описать видимый признак проще: «полосы», «цвет», «приводка», «царапины».</p></div>`;
 const count=document.getElementById('defectResultCount'); if(count)count.textContent=`Показано ${list.length} из ${defectLibrary.length}`;
}
function setDefectFilter(filter){window.__defectFilter=filter;document.querySelectorAll('#defectFilters .kb-chip').forEach(b=>b.classList.toggle('active',(b.dataset.filter||'')===filter));filterDefects(document.getElementById('defectSearch')?.value||'')}
function clearDefectSearch(){const i=document.getElementById('defectSearch');if(i)i.value='';window.__defectFilter='';document.querySelectorAll('#defectFilters .kb-chip').forEach((b,i)=>b.classList.toggle('active',i===0));filterDefects('')}

function filterKnowledge(q){
 const cat=(document.getElementById('kbCat')||{}).value||window.__kbCategory||''; const term=(q||document.getElementById('kbSearch')?.value||'').toLowerCase().trim();
 const list=knowledgeArticles.filter(a=>(!cat||a[1]===cat)&&(!term||(a[0]+' '+a[1]+' '+a[2]+' '+(a[4]||'')+' '+(a[5]||'')).toLowerCase().includes(term)));
 const grid=document.getElementById('kbGrid'); if(grid)grid.innerHTML=list.length?knowledgeCardsHtml(list):`<div class="card kb-empty"><div class="iconbox">?</div><h3>Ничего не найдено</h3><p>Попробуйте другое слово или выберите другой раздел.</p></div>`;
 const count=document.getElementById('kbResultCount'); if(count)count.textContent=`Показано ${list.length} из ${knowledgeArticles.length}`;
}
function setKnowledgeCategory(cat){window.__kbCategory=cat;document.querySelectorAll('.kb-chip').forEach(b=>b.classList.toggle('active',(b.dataset.cat||'')===cat));filterKnowledge(document.getElementById('kbSearch')?.value||'')}
function clearKnowledgeSearch(){const i=document.getElementById('kbSearch');if(i)i.value='';window.__kbCategory='';document.querySelectorAll('.kb-chip').forEach(b=>b.classList.toggle('active',!b.dataset.cat));filterKnowledge('')}
function kbArticle(i){
 const a=knowledgeArticles[+i]; if(!a)return knowledgePage();
 const related=knowledgeArticles.filter((x,idx)=>idx!==+i&&x[1]===a[1]).slice(0,6);
 const title=a[0],cat=a[1],lead=a[2],detail=a[4]||'',practice=a[5]||'';
 return `<main class="section"><div class="container"><a class="btn btn-ghost" href="#/knowledge">← База знаний</a><article class="card article-main kb-article" style="margin-top:20px"><div class="eyebrow">${esc(cat)}</div><h1>${esc(title)}</h1><p class="lead">${esc(lead)}</p><div class="kb-article-layout"><div><img class="article-image kb-article-image" src="${kbImageFor(a[0],a[1])}" alt="${esc(title)}" loading="lazy" decoding="async" referrerpolicy="no-referrer" onerror="this.onerror=null;this.classList.add('image-fallback')"><div class="small muted kb-image-credit">Источник изображения: <a href="${esc(knowledgeImageSourceByTitle[title]||'#')}" target="_blank" rel="noopener noreferrer">Wikimedia Commons</a></div><div class="kb-reading"><section class="kb-section"><h2>Что это</h2><p>${esc(detail)}</p></section><section class="kb-section"><h2>Практический смысл</h2><p>${esc(practice)}</p></section><section class="kb-section"><h2>Как работать с понятием</h2><p>Сначала определите, где этот термин находится в технологической цепочке. Затем отделите нормальное состояние от отклонения и выберите способ проверки. Если речь идёт о дефекте или измеряемом параметре, фиксируйте исходное состояние до корректировки и подтверждайте результат после неё.</p></section></div></div><aside class="kb-aside"><div class="kb-aside-card"><span class="tag">${esc(cat)}</span><b>Связь с производством</b><p>Термин должен помогать объяснять конкретное действие, наблюдение или критерий качества, а не оставаться только словарным определением.</p></div><div class="kb-aside-card"><b>Важно</b><p>Конкретные производственные режимы, допуски и настройки определяются технологией, документацией машины и локальными инструкциями PrintStyle.</p></div></aside></div></article><div class="kb-related"><div class="section-head"><div><div class="eyebrow">RELATED</div><h2>Похожие термины</h2></div><a class="small" href="#/knowledge">Ко всей базе →</a></div><div class="grid grid-3">${related.map(x=>`<a class="card" href="#/kb/${knowledgeArticles.indexOf(x)}"><span class="tag">${esc(x[1])}</span><h3>${esc(x[0])}</h3><p>${esc(x[2])}</p></a>`).join('')}</div></div></div></main>`
}
function defectPage(i){if(!isAuthenticated())return diagnosticsAccessPage('diagnostics');const d=defectLibrary[+i];if(!d)return diagnosticsPage();const related=defectLibrary.map((x,idx)=>({x,idx})).filter(x=>x.idx!==+i&&((x.x[1]+' '+x.x[0]).toLowerCase().split(/\s+/).some(w=>w.length>5&&d[0].toLowerCase().includes(w)))).slice(0,3);return `<main class="section defect-detail-page"><div class="container"><a class="btn btn-ghost" href="#/diagnostics">← Все дефекты</a><div class="defect-detail-hero card"><div><span class="tag">ДИАГНОСТИКА · ${+i+1} / ${defectLibrary.length}</span><h1>${esc(d[0])}</h1><p class="lead">${esc(d[1])}</p></div><img class="defect-detail-image" src="${esc(d[5]||'assets/defects/fallback.svg')}" alt="${esc(d[0])}" onerror="this.onerror=null;this.classList.add('image-fallback')"></div><div class="defect-detail-grid"><article class="card diagnostic-algorithm"><div class="eyebrow">АЛГОРИТМ</div><h2>Как искать причину</h2><div class="diag-step"><b>01</b><div><strong>Зафиксируйте признак</strong><p>${esc(d[1])}</p></div></div><div class="diag-step"><b>02</b><div><strong>Проверьте первое направление</strong><p>${esc(d[2])}</p></div></div><div class="diag-step"><b>03</b><div><strong>Сравните результат после проверки</strong><p>Меняйте только один фактор за раз, если это допускается технологией. Зафиксируйте, исчез ли дефект, изменился ли его характер и повторяется ли он дальше.</p></div></div><div class="diag-step warning"><b>04</b><div><strong>Не делайте случайных регулировок</strong><p>${esc(d[3])}</p></div></div></article><aside class="card defect-side"><span class="tag">ПРАКТИКА</span><h2>Что важно зафиксировать</h2><ul><li>на каком участке листа появился признак;</li><li>повторяется ли он на следующих листах;</li><li>через какой интервал повторяется;</li><li>что изменилось перед появлением;</li><li>какой результат получен после проверки.</li></ul><a class="btn btn-primary" href="#/course/defects">Изучить диагностику в курсе →</a></aside></div><div class="notice">Справочный материал. Точная диагностика выполняется по локальной технологии конкретного производства и документации оборудования.</div>${related.length?`<section class="defect-related"><div class="section-head"><div><div class="eyebrow">Похожие случаи</div><h2>Что проверить рядом</h2></div></div><div class="grid grid-3">${related.map(r=>`<a class="card" href="#/defect/${r.idx}"><span class="tag">ДЕФЕКТ</span><h3>${esc(r.x[0])}</h3><p>${esc(r.x[1])}</p></a>`).join('')}</div></section>`:''}</div></main>`}

function jobsPage(){return `<main class="section"><div class="container"><div class="eyebrow">CAREER</div><h1 style="font-size:60px">Работа в PrintStyle</h1><p class="lead">Академия может быть первым этапом подготовки кандидата перед практикой и интервью.</p><div class="grid grid-3" style="margin-top:35px">${vacancies.map(v=>`<article class="card job-card"><span class="tag">${v[2]}</span><h2>${v[0]}</h2><p><b>Компания:</b> ${v[1]}</p><p><b>Требования:</b> ${v[3]}</p><p><b>Условия:</b> ${v[4]}</p><button class="btn btn-primary" style="margin-top:18px" onclick="openAuth('register')">Создать профиль для отклика</button></article>`).join('')}</div><div class="banner" style="margin-top:20px"><div><h2>Ваше обучение можно связать с карьерным маршрутом</h2><p class="muted">После прохождения курсов профиль содержит прогресс, результаты тестов и сертификаты.</p></div><a class="btn btn-primary" href="#/dashboard">Мой профиль →</a></div></div></main>`}
function aboutPage(){const photos=[['https://framerusercontent.com/images/tpm3xNy5OyzPT702QhSW9zCFI.jpg?height=400&width=1590','Производственная площадка Printstyle','Фотография с официального сайта Printstyle','https://printstyle.com/'],['https://framerusercontent.com/images/gYmjMJgbXrWmQeFFlD3JZO9jyzs.jpeg','Готовая продукция','Пример продукции Printstyle — этикеточная печать и отделка','https://printstyle.com/'],['https://framerusercontent.com/images/fgDjK20s6YIAzUbjP2rFruhVxk.webp','Премиальная этикетка','Пример готовых этикеток с декоративной отделкой','https://printstyle.com/products'],['https://framerusercontent.com/images/0Wk1gaqTVPHhkZHPjw5MSjX1zo.jpeg','Этикетки в производстве','Пример серийной продукции Printstyle','https://printstyle.com/products']];return `<main class="section company-page"><div class="container"><div class="eyebrow">О КОМПАНИИ</div><h1 style="font-size:clamp(44px,6vw,70px)">Полиграфическая компания Printstyle</h1><p class="lead">PrintStyle Academy связана с реальным производством. Поэтому здесь важно понимать, для какой профессиональной среды создаётся обучение: Printstyle — компания, специализирующаяся на производстве этикеточной продукции и технологиях её печати и отделки.</p><div class="company-hero"><div><div class="eyebrow">PRINTSTYLE · С 1996 ГОДА</div><h2>От идеи и проектирования до готовой продукции</h2><p>На официальном сайте Printstyle компания указывает, что работает с 1996 года и располагает полным циклом производства. В описании производства подчёркиваются современное оборудование, профессиональная команда и контроль качества на этапах выпуска продукции.</p><a class="btn btn-primary" href="https://printstyle.com/" target="_blank" rel="noopener">Официальный сайт Printstyle →</a></div><img src="${photos[0][0]}" alt="Производственная площадка Printstyle"></div><div class="company-stats">${[['16 000','м² производственных площадей'],['180+','сотрудников'],['1 500+','проектов в год'],['100+','постоянных клиентов'],['25+','регионов доставки'],['6','этапов ОТК и собственная лаборатория']].map(x=>`<div class="company-stat"><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join('')}</div><div class="section-head" style="margin-top:70px"><div><div class="eyebrow">ЧЕМ ЗАНИМАЕТСЯ PRINTSTYLE</div><h2>Производство, где печатник видит весь технологический контекст</h2><p class="section-intro">На официальном сайте представлены направления офсетной печати этикеток, печати по плёнке и In-Mold, влагостойких и металлизированных решений, а также различные виды лакирования и тиснения.</p></div></div><div class="grid grid-4 company-gallery">${photos.map(x=>`<figure class="company-photo card"><img src="${x[0]}" alt="${x[1]}"><figcaption><strong>${x[1]}</strong><span>${x[2]}</span><a href="${x[3]}" target="_blank" rel="noopener">Источник фотографии ↗</a></figcaption></figure>`).join('')}</div><div class="grid grid-2 company-values" style="margin-top:22px"><div class="card"><div class="iconbox">01</div><h2>Почему это важно для Академии</h2><p>Учебные материалы должны быть связаны с настоящей производственной средой. Поэтому в курсах появляются конкретные виды оборудования, материалы, реальные печатные процессы и разбор дефектов.</p></div><div class="card"><div class="iconbox">02</div><h2>Почему это важно для будущего печатника</h2><p>Чем раньше человек понимает, что результат зависит от материала, машины, краски, увлажнения, приводки, сушки и контроля, тем осмысленнее становится его дальнейшая практика.</p></div></div><div class="notice" style="margin-top:22px"><b>Источник корпоративной информации:</b> официальный сайт Printstyle. Показатели и направления производства могут обновляться самой компанией; в Академии они используются как контекст, а не как гарантия трудоустройства или конкретных условий работы.</div></div></main>`}
function sourcesPage(){return `<main class="section"><div class="container"><div class="eyebrow">MEDIA SOURCES</div><h1 style="font-size:58px">Фотографии и лицензии</h1><p class="lead">Для первой версии использованы открытые материалы с указанием источника. В админке будущей версии источник, автор и лицензия должны храниться вместе с медиа.</p><div class="grid grid-3" style="margin-top:30px">${mediaCredits.map(m=>`<article class="card source-card"><img src="${m[1]}" alt="${esc(m[0])}"><h3>${m[0]}</h3><p>${m[2]}</p><span class="pill">${m[3]}</span><a class="small" href="${m[4]}" target="_blank" rel="noopener">Открыть источник ↗</a></article>`).join('')}</div></div></main>`}

function dashboard(){
 const u=state.user||{};
 const allCourses=[...curriculumCourses(),...mandatoryCourses()];
 const started=allCourses.filter(c=>(state.progress[c.id]||0)>0);
 const completed=allCourses.filter(c=>(state.progress[c.id]||0)>=100).length;
 const allComplete=completed===allCourses.length;
 const current=allCourses.find(c=>{const p=state.progress[c.id]||0;return p>0&&p<100})||allCourses.find(c=>(state.progress[c.id]||0)<100)||allCourses[allCourses.length-1];
 const currentProgress=current?courseLessonProgress(current):0;
 const currentLesson=current?firstIncompleteLesson(current):0;
 const currentLessonData=current?.lessons?.[currentLesson];
 const nextHref=current?`#/course/${encodeURIComponent(current.id)}?lesson=${Math.max(0,currentLesson)}`:'#/courses';
 const completedLessonCount=Object.keys(state.completedLessons||{}).length;
 const totalLessonCount=allCourses.reduce((n,c)=>n+c.lessons.length,0);
 const testCount=Object.keys(state.results||{}).length;
 const diagnosticCount=Object.values(state.diagnostics||{}).filter(x=>x&&x.completed).length;
 const skillData=printerSkills();
 const readiness=careerReadiness();
 const overallProgress=overall();
 const fullName=esc((u.name+' '+(u.surname||'')).trim()||'Печатник');
 const lastActivity=Object.entries(state.completedLessons||{}).map(([key,date])=>{const [cid,idx]=key.split('::');const c=course(cid);const i=Number(idx);return {date,c,i,l:c?.lessons?.[i]};}).filter(x=>x.c&&x.l).sort((a,b)=>new Date(b.date)-new Date(a.date))[0];
 const remaining=Math.max(0,allCourses.length-completed);
 const pathLabel=allComplete?'Маршрут завершён':started.length?'Продолжаете профессиональный маршрут':'Начните с первого шага';
 const nextCopy=allComplete
   ? `Вы завершили все доступные курсы. Можно повторить материал, открыть диагностику или перейти к карьерному профилю.`
   : started.length
   ? `Вы остановились на курсе «${esc(current.title)}». Продолжите с урока ${currentLesson+1}: «${esc(currentLessonData?.title||'следующая тема')}».`
   : `Начните с курса «${esc(current.title)}». После первого урока Академия будет сохранять ваш прогресс и показывать следующий шаг.`;
 return `<main class="dashboard dashboard-v3"><aside class="side"><div class="dashboard-brand"><div class="eyebrow">MY ACADEMY</div><strong>Профиль печатника</strong></div><a class="active" href="#/dashboard">Мой путь</a><a href="#/courses">Мои курсы</a><a href="#/diagnostics">Диагностика</a><a href="#/knowledge">База знаний</a><a href="#/verify">Сертификаты</a><a href="#/jobs">Вакансии</a><div class="side-divider"></div><a href="#/admin">Admin demo</a></aside><section class="dash-main">
 <section class="dashboard-welcome"><div><div class="eyebrow">PRINTSTYLE ACADEMY · МОЙ ПУТЬ</div><h1>Здравствуйте, ${fullName}</h1><p>${esc(u.profession||'Печатник')} · ${esc(u.experience||'Опыт не указан')}${u.city?' · '+esc(u.city):''}</p></div><div class="dashboard-overall"><span>Общий прогресс</span><b>${overallProgress}%</b><div class="progress"><i style="width:${overallProgress}%"></i></div><small>${completed} из ${allCourses.length} курсов завершено</small></div></section>
 <section class="dashboard-next card"><div class="next-copy"><span class="tag">${pathLabel}</span><h2>${allComplete?'Следующий уровень':started.length?'Продолжить обучение':'Начать обучение'}</h2><p>${nextCopy}</p><div class="next-actions"><a class="btn btn-primary" href="${allComplete?'#/diagnostics/trainer':nextHref}">${allComplete?'Запустить тренажёр':started.length?'Продолжить урок':'Начать первый урок'} →</a><a class="btn btn-ghost" href="#/diagnostics">Проверить себя</a></div></div><div class="next-meter"><div class="meter-ring"><b>${currentProgress}%</b><span>курс</span></div><small>${esc(current.level)} · ${current.lessons.length} уроков</small></div></section>
 <section class="dashboard-quick"><a class="card quick-card" href="${allComplete?'#/diagnostics/trainer':nextHref}"><span class="quick-icon">▶</span><div><b>${allComplete?'Следующий шаг':'Продолжить'}</b><small>${allComplete?'Диагностический тренажёр':esc(current.title)+' · урок '+(currentLesson+1)}</small></div><span class="quick-arrow">→</span></a><a class="card quick-card" href="#/diagnostics"><span class="quick-icon">⌁</span><div><b>Диагностика</b><small>Потренировать профессиональное мышление</small></div><span class="quick-arrow">→</span></a><a class="card quick-card" href="#/knowledge"><span class="quick-icon">?</span><div><b>База знаний</b><small>Найти термин, материал или технологию</small></div><span class="quick-arrow">→</span></a></section>
 <section class="dashboard-stats"><div class="card stat"><div class="kpi">КУРСОВ НАЧАТО</div><div class="v">${started.length}</div><small>${completed} завершено · ${remaining} впереди</small></div><div class="card stat"><div class="kpi">УРОКОВ ПРОЙДЕНО</div><div class="v">${completedLessonCount}</div><small>из ${totalLessonCount}</small></div><div class="card stat"><div class="kpi">ТЕСТОВ ПРОЙДЕНО</div><div class="v">${testCount}</div><small>${state.certs.length} сертификат(ов)</small></div><div class="card stat"><div class="kpi">ДИАГНОСТИК ПРОЙДЕНО</div><div class="v">${diagnosticCount}</div><small>из ${DIAGNOSTIC_TRAINER_CASES.length} сценариев</small></div><div class="card stat"><div class="kpi">ЗАКЛАДОК</div><div class="v">${state.bookmarks.length}</div><small>сохранённых материалов</small></div></section>
 <section class="dashboard-section learning-roadmap"><div class="section-head"><div><div class="eyebrow">YOUR ROUTE</div><h2>Ваш путь в Академии</h2><p class="muted">Проходите программу последовательно. На каждом шаге видно, где вы находитесь и что открывается дальше.</p></div><a class="btn btn-ghost" href="#/courses">Изменить маршрут →</a></div><div class="roadmap-list">${allCourses.map((c,i)=>{const p=state.progress[c.id]||0;const isCurrent=c.id===current?.id;const status=p>=100?'done':isCurrent?'current':p>0?'active':'locked';return `<div class="roadmap-item ${status}"><span class="roadmap-number">${p>=100?'✓':String(i+1).padStart(2,'0')}</span><div class="roadmap-main"><div><span class="skill-kicker">${esc(c.level)}</span><h3>${esc(c.title)}</h3><p>${c.lessons.length} уроков · ${esc(c.duration)}</p></div><div class="roadmap-progress"><div class="progress"><i style="width:${p}%"></i></div><b>${p}%</b></div></div><a class="btn btn-ghost" href="#/course/${c.id}?lesson=${Math.max(0,firstIncompleteLesson(c))}">${p>=100?'Повторить':p>0?'Продолжить':'Открыть'}</a></div>`}).join('')}</div></section>
 <section class="dashboard-section"><div class="section-head"><div><div class="eyebrow">SKILL MAP</div><h2>Карта навыков печатника</h2><p class="muted">Быстрый обзор профессиональных направлений. Подробное подтверждение навыков — ниже, в матрице компетенций.</p></div><span class="pill">${readiness}% готовности</span></div><div class="skill-grid">${skillData.map(s=>`<div class="card skill-card"><div class="skill-top"><div><span class="skill-kicker">${esc(s.group)}</span><h3>${esc(s.name)}</h3></div><b>${s.value}%</b></div><div class="progress"><i style="width:${s.value}%"></i></div><small>${esc(s.level)} · ${esc(s.detail)}</small></div>`).join('')}</div></section>${competencyMatrix()}
 <section class="dashboard-activity-grid"><div class="card activity-card"><div class="eyebrow">ПОСЛЕДНЯЯ АКТИВНОСТЬ</div>${lastActivity?`<h3>${esc(lastActivity.l.title)}</h3><p>${esc(lastActivity.c.title)} · урок ${lastActivity.i+1}</p><small>${new Date(lastActivity.date).toLocaleDateString('ru-RU')}</small><a class="btn btn-ghost" href="#/course/${lastActivity.c.id}?lesson=${lastActivity.i}">Вернуться к уроку →</a>`:`<h3>Обучение ещё не начато</h3><p>Начните первый урок — здесь появится ваша история обучения.</p><a class="btn btn-primary" href="${nextHref}">Начать обучение →</a>`}</div><div class="card activity-card"><div class="eyebrow">СЛЕДУЮЩИЙ РЕЗУЛЬТАТ</div><h3>${currentProgress>=100?'Перейти к следующему курсу':`Закрыть курс «${esc(current.title)}»`}</h3><p>${currentProgress>=100?'Текущий курс завершён. Откройте следующий модуль из вашего маршрута.':`Осталось ${Math.max(0,current.lessons.length-current.lessons.filter((_,i)=>isLessonDone(current.id,i)).length)} уроков.`}</p><a class="btn btn-primary" href="${nextHref}">${currentProgress>=100?'Открыть следующий':'Продолжить курс'} →</a></div></section>
 <section class="dashboard-lower"><div class="card dashboard-profile-card"><div class="section-head"><div><div class="eyebrow">PROFILE</div><h2>Профиль специалиста</h2></div><button class="btn btn-ghost" onclick="openProfileEdit()">Редактировать</button></div><div class="profile-identity"><div class="profile-avatar">${esc((u.name||'У').slice(0,1).toUpperCase())}</div><div><h3>${fullName}</h3><p>${esc(u.profession||'Печатник')}</p></div></div><div class="profile-grid profile-grid-v3"><div><span>Опыт</span><b>${esc(u.experience||'Не указан')}</b></div><div><span>Город</span><b>${esc(u.city||'Не указан')}</b></div><div><span>Оборудование</span><b>${esc(u.machines||'Не указано')}</b></div><div><span>Email</span><b>${esc(u.email||'')}</b></div></div></div><div class="card career-card"><div class="eyebrow">CAREER</div><h2>Готовность к работе</h2><div class="career-score"><b>${readiness}%</b><span>профиль подготовки</span></div><div class="progress"><i style="width:${readiness}%"></i></div><p class="muted">Заполненный профиль + обучение + результаты тестов формируют основу профессионального профиля.</p><a class="btn btn-primary" href="#/jobs">Посмотреть вакансии →</a></div></section>
 ${state.certs.length?`<section class="dashboard-section"><div class="section-head"><div><div class="eyebrow">CERTIFICATES</div><h2>Мои сертификаты</h2></div><a class="btn btn-ghost" href="#/verify">Проверить сертификат</a></div><div class="certificate-list">${state.certs.map(c=>`<div class="card certificate-mini"><div><span class="tag">PRINTSTYLE ACADEMY</span><h3>${esc(c.program)}</h3><p>№ ${esc(c.id)} · ${esc(c.date)}</p></div><a class="btn btn-ghost" href="#/verify">Проверить →</a></div>`).join('')}</div></section>`:''}
 </section></main>`
}
function pluralize(n,one,few,many){const m=n%100;const x=n%10;return m>=11&&m<=14?many:(x===1?one:(x>=2&&x<=4?few:many))}
function courseProgressValue(id){return Math.max(0,Math.min(100,Number(state.progress[id]||0)))}
function printerSkills(){
 const skills=[
  {group:'База профессии',name:'Основы печати',ids:['intro'],evidence:[['Курс','intro']]},
  {group:'Технология',name:'Офсетная печать',ids:['poly'],evidence:[['Курс','poly']]},
  {group:'Материалы',name:'Материалы и подготовка',ids:['materials'],evidence:[['Курс','materials']]},
  {group:'Цвет',name:'Цвет и краска',ids:['poly','materials'],evidence:[['Курсы','poly','materials']]},
  {group:'Приводка',name:'Приводка и геометрия',ids:['poly','xl105','xl106','roland'],evidence:[['Курсы','poly','xl105','xl106','roland']]},
  {group:'Диагностика',name:'Диагностика дефектов',ids:['defects'],diagnostics:true,evidence:[['Курс','defects']]},
  {group:'Оборудование',name:'Heidelberg XL 105',ids:['xl105'],evidence:[['Курс','xl105']]},
  {group:'Оборудование',name:'Heidelberg XL 106',ids:['xl106'],evidence:[['Курс','xl106']]},
  {group:'Оборудование',name:'Roland',ids:['roland'],evidence:[['Курс','roland']]},
  {group:'Безопасность',name:'Производственная безопасность',ids:['safety'],evidence:[['Курс','safety']]}
 ];
 return skills.map(s=>{
   const courseVals=s.ids.map(courseProgressValue);
   const courseAvg=Math.round(courseVals.reduce((a,b)=>a+b,0)/courseVals.length);
   const diagnosticDone=s.diagnostics?Object.values(state.diagnostics||{}).filter(x=>x&&x.completed).length:0;
   const diagnosticBonus=s.diagnostics?Math.min(100,diagnosticDone*20):0;
   const value=s.diagnostics?Math.round(courseAvg*.65+diagnosticBonus*.35):courseAvg;
   const courseDone=s.ids.filter(id=>courseProgressValue(id)>=100).length;
   const testCount=s.ids.reduce((n,id)=>n+(state.results?.[id]!=null?1:0),0);
   const evidenceCount=courseDone+(s.diagnostics?diagnosticDone:0)+(testCount?1:0);
   let level=value>=100?'Подтверждено':value>=70?'Освоено':value>0?'Изучается':'Не начато';
   let detail=value>=100?'Есть подтверждение через обучение и практические проверки':value>0?`${level} · ${value}% прогресса`:'Начните связанный курс';
   return {...s,value,level,detail,courseDone,testCount,diagnosticDone,evidenceCount};
 });
}
function skillEvidenceHtml(s){
 const links=s.ids.map(id=>{const c=course(id);if(!c)return '';const p=courseProgressValue(id);return `<a class="skill-evidence-link" href="#/course/${encodeURIComponent(id)}?lesson=${Math.max(0,firstIncompleteLesson(c))}"><span>Курс</span><b>${esc(c.title)}</b><small>${p}%</small></a>`}).join('');
 const diag=s.diagnostics?`<a class="skill-evidence-link" href="#/diagnostics/trainer"><span>Практика</span><b>Диагностический тренажёр</b><small>${s.diagnosticDone} пройдено</small></a>`:'';
 return links+diag;
}
function competencyMatrix(){
 const skills=printerSkills();
 const confirmed=skills.filter(s=>s.value>=100).length;
 const active=skills.filter(s=>s.value>0&&s.value<100).length;
 const notStarted=skills.filter(s=>s.value===0).length;
 return `<section class="dashboard-section competency-section"><div class="section-head"><div><div class="eyebrow">COMPETENCY MATRIX · V101</div><h2>Матрица компетенций</h2><p class="muted">Навык формируется из реального обучения и практики. Никаких процентов «из воздуха»: под каждым направлением видно, чем оно подтверждается.</p></div><div class="competency-summary"><span><b>${confirmed}</b> подтверждено</span><span><b>${active}</b> в работе</span><span><b>${notStarted}</b> не начато</span></div></div><div class="competency-grid">${skills.map(s=>`<article class="card competency-card"><div class="competency-head"><div><span class="skill-kicker">${esc(s.group)}</span><h3>${esc(s.name)}</h3></div><span class="competency-level level-${s.level==='Подтверждено'?'confirmed':s.level==='Освоено'?'mastered':s.level==='Изучается'?'learning':'new'}">${s.level}</span></div><div class="competency-value"><b>${s.value}%</b><div class="progress"><i style="width:${s.value}%"></i></div></div><p class="competency-detail">${esc(s.detail)}</p><div class="skill-evidence"><div class="eyebrow">ДОКАЗАТЕЛЬСТВА НАВЫКА</div>${skillEvidenceHtml(s)}</div></article>`).join('')}</div></section>`;
}
function careerReadiness(){
 const skills=printerSkills();
 const learning=Math.round(skills.reduce((a,s)=>a+s.value,0)/skills.length);
 const profileFields=[state.user?.profession,state.user?.experience,state.user?.city,state.user?.machines].filter(Boolean).length;
 const profile=Math.round(profileFields/4*20);
 const tests=Math.min(10,Object.keys(state.results).length*2);
 return Math.min(100,Math.round(learning*.7+profile+tests));
}
function openProfileEdit(){
 const u=state.user||{};const m=document.createElement('div');m.className='modal';m.id='profileEditModal';m.innerHTML=`<div class="modal-box"><div class="modal-head"><div><div class="eyebrow">PROFILE</div><h2>Редактировать профиль</h2></div><button class="close" onclick="this.closest('.modal').remove()">×</button></div><form onsubmit="saveProfileEdit(event)"><div class="form-grid"><div><label class="label">Имя</label><input class="input" id="pname" required value="${esc(u.name||'')}"></div><div><label class="label">Фамилия</label><input class="input" id="psurname" value="${esc(u.surname||'')}"></div><div><label class="label">Email</label><input class="input" id="pemail" type="email" required value="${esc(u.email||'')}"></div><div><label class="label">Телефон</label><input class="input" id="pphone" value="${esc(u.phone||'')}"></div><div><label class="label">Страна</label><input class="input" id="pcountry" value="${esc(u.country||'')}"></div><div><label class="label">Город</label><input class="input" id="pcity" value="${esc(u.city||'')}"></div><div><label class="label">Опыт работы</label><input class="input" id="pexp" value="${esc(u.experience||'')}"></div><div><label class="label">Профессия</label><input class="input" id="pprof" value="${esc(u.profession||'Печатник')}"></div><div class="full"><label class="label">Оборудование</label><input class="input" id="pmachines" value="${esc(u.machines||'')}" placeholder="Heidelberg XL 105, XL 106, Roland..."></div></div><button class="btn btn-primary" style="width:100%;margin-top:18px">Сохранить профиль</button></form></div>`;document.body.appendChild(m)
}
function saveProfileEdit(e){e.preventDefault();state.user={...state.user,name:document.getElementById('pname').value,surname:document.getElementById('psurname').value,email:document.getElementById('pemail').value,phone:document.getElementById('pphone').value,country:document.getElementById('pcountry').value,city:document.getElementById('pcity').value,experience:document.getElementById('pexp').value,profession:document.getElementById('pprof').value,machines:document.getElementById('pmachines').value};save();document.getElementById('profileEditModal')?.remove();toast('Профиль обновлён');render()}

function loginPrompt(){return `<main class="section"><div class="container"><div class="card" style="max-width:650px;margin:auto;text-align:center"><div class="eyebrow">PRIVATE AREA</div><h1 style="font-size:48px">Войдите в Академию</h1><p class="lead">Личный кабинет хранит прогресс, результаты тестов и сертификаты.</p><button class="btn btn-primary" onclick="openAuth('login')">Войти</button></div></div></main>`}

function adminPage(){return `<main class="admin-shell"><aside class="admin-side"><div class="eyebrow">CMS / LMS</div><h3>PrintStyle Academy</h3><a href="#/admin">Обзор</a><a href="#/courses">Курсы</a><a href="#/knowledge">Медиа</a><a href="#/jobs">Вакансии</a><a href="#/sources">Лицензии</a></aside><section class="admin-main"><div class="section-head"><div><div class="eyebrow">CONTENT CONTROL</div><h1 style="font-size:44px">Административная панель</h1></div><span class="pill">MVP / DEMO</span></div><div class="stat-grid"><div class="card stat"><div class="kpi">КУРСЫ</div><div class="v">${courses.length}</div></div><div class="card stat"><div class="kpi">УРОКИ</div><div class="v">${courses.reduce((n,c)=>n+c.lessons.length,0)}</div></div><div class="card stat"><div class="kpi">ВОПРОСЫ</div><div class="v">${courses.reduce((n,c)=>n+c.questions.length,0)}</div></div><div class="card stat"><div class="kpi">MEDIA</div><div class="v">${mediaCredits.length}</div></div></div><div class="grid grid-2" style="margin-top:20px"><div class="card"><h2>Контентная модель</h2><p class="muted">Курс → урок → визуальный материал → тест. В production-версии эти сущности должны редактироваться через CMS, а не в JavaScript.</p><div class="meta"><span>✓ Тексты</span><span>✓ Фото</span><span>✓ Тесты</span><span>✓ Источники</span></div></div><div class="card"><h2>HR-профиль</h2><p class="muted">В production-версии HR получает отдельную роль и видит только разрешённые данные кандидата: опыт, оборудование, прогресс, результаты и отклики.</p><a class="btn btn-primary" href="#/jobs">Перейти к вакансиям</a></div></div><div class="card" style="margin-top:20px"><h2>Курсы и наполнение</h2><div class="table-wrap"><table class="table"><thead><tr><th>Курс</th><th>Уроки</th><th>Вопросы</th><th>Изображение</th></tr></thead><tbody>${[...curriculumCourses(),...mandatoryCourses()].map(c=>`<tr><td>${c.title}</td><td>${c.lessons.length}</td><td>${c.questions.length}</td><td><span class="pill">Есть</span></td></tr>`).join('')}</tbody></table></div></div></section></main>`}

function verifyPage(){return `<main class="section"><div class="container"><div class="eyebrow">CERTIFICATE VERIFICATION</div><h1 style="font-size:58px">Проверка сертификата</h1><p class="lead">Введите номер сертификата, полученного в этой демо-версии.</p><div class="search"><input class="input" id="certId" placeholder="PS-2026-000123"><button class="btn btn-primary" onclick="verifyCert()">Проверить</button></div><div id="certResult"></div></div></main>`}
function verifyCert(){const id=(document.getElementById('certId')?.value||'').trim();const c=state.certs.find(x=>x.id===id);document.getElementById('certResult').innerHTML=c?`<div class="cert"><div class="eyebrow" style="color:#1f4f9d">PRINTSTYLE ACADEMY</div><h2>Certificate</h2><p>Настоящим подтверждается, что</p><h2 style="font-size:30px">${esc(c.name)}</h2><p>успешно завершил(а) программу</p><h3>${esc(c.program)}</h3><div class="cert-meta"><b>№ ${esc(c.id)}</b><span>${esc(c.date)}</span><span>Статус: действителен</span><div class="qr"></div></div></div>`:`<div class="notice error">Сертификат не найден.</div>`}

function openAuth(mode){const m=document.createElement('div');m.className='modal';m.id='authModal';m.dataset.returnHash=location.hash||'#/dashboard';m.innerHTML=`<div class="modal-box"><div class="modal-head"><div><div class="eyebrow">${mode==='login'?'AUTHORIZATION':'REGISTRATION'}</div><h2>${mode==='login'?'Вход в Академию':'Создать аккаунт'}</h2></div><button class="close" onclick="this.closest('.modal').remove()">×</button></div>${mode==='login'?`<form onsubmit="doLogin(event)"><label class="label">Email</label><input class="input" id="email" type="email" required placeholder="you@example.com"><label class="label" style="margin-top:12px">Пароль</label><input class="input" id="password" type="password" required><button class="btn btn-primary" style="width:100%;margin-top:18px">Войти</button><p class="muted small">Демо-режим: серверной авторизации пока нет.</p></form>`:`<form onsubmit="doRegister(event)"><div class="form-grid"><div><label class="label">Имя</label><input class="input" id="rname" required></div><div><label class="label">Фамилия</label><input class="input" id="rsurname" required></div><div><label class="label">Email</label><input class="input" id="remail" type="email" required></div><div><label class="label">Телефон</label><input class="input" id="rphone"></div><div><label class="label">Страна</label><input class="input" id="rcountry"></div><div><label class="label">Город</label><input class="input" id="rcity"></div><div><label class="label">Опыт работы</label><input class="input" id="rexp" placeholder="Например, 5 лет"></div><div><label class="label">Профессия</label><input class="input" id="rprof" value="Печатник"></div><div class="full"><label class="label">Оборудование</label><input class="input" id="rmachines" placeholder="Heidelberg XL 105, XL 106, Roland..."></div><div class="full"><label><input type="checkbox" required> <span class="small muted">Согласен с правилами Академии и обработкой персональных данных.</span></label></div></div><button class="btn btn-primary" style="width:100%;margin-top:18px">Создать аккаунт</button></form>`}</div>`;document.body.appendChild(m)}
function doLogin(e){e.preventDefault();const modal=document.getElementById('authModal');const returnHash=modal?.dataset.returnHash||'#/dashboard';state.user={name:'Анатолий',surname:'',email:document.getElementById('email').value,profession:'Печатник',experience:'Не указано',machines:'Heidelberg XL 105'};save();modal?.remove();toast('Вы вошли в Академию');location.hash=returnHash}
function doRegister(e){e.preventDefault();const modal=document.getElementById('authModal');const returnHash=modal?.dataset.returnHash||'#/dashboard';state.user={name:rname.value,surname:rsurname.value,email:remail.value,phone:rphone.value,country:rcountry.value,city:rcity.value,experience:rexp.value,profession:rprof.value,machines:rmachines.value};save();modal?.remove();toast('Профиль создан');location.hash=returnHash}
function logout(){state.user=null;save();location.hash='/';toast('Вы вышли из аккаунта')}
function toggleMenu(){const n=document.getElementById('navlinks');n.style.display=n.style.display==='flex'?'none':'flex'}

window.addEventListener('hashchange',()=>{const p=location.hash.replace(/^#\/?/,'').split('?')[0];if(p.startsWith('course-test/')){const id=p.split('/')[1];renderCourseTest(id);return}render();window.scrollTo(0,0)});
applyTheme();
window.addEventListener('load',()=>{const p=location.hash.replace(/^#\/?/,'').split('?')[0];if(p.startsWith('course-test/')){renderCourseTest(p.split('/')[1]);return}render()});


