/* STAGE 3.5 — course QA fixes: XL106/Roland question quality + lesson-answer integrity */
(function(){
  function lessonText(l){
    return [l.title,l.goal,l.intro, ...(Array.isArray(l.sections)?l.sections.flatMap(x=>[x.h,x.p]):[]), ...(l.bullets||[])].filter(Boolean).join(' ');
  }
  function makeLessonQuestions(l){
    const b=Array.isArray(l.bullets)?l.bullets.filter(Boolean):[];
    if(!b.length) return l.questions||[];
    const a=b[0], c=b[1]||b[0], d=b[2]||b[0];
    return [
      {type:'single',q:'Что прямо указано в материале этого урока?',options:[a,'Игнорировать этот фактор.','Менять параметры без проверки.','Оценивать процесс только по скорости.'],correct:[0],explanation:'Правильный ответ сформулирован непосредственно в контрольных ориентирах урока.'},
      {type:'case',q:'В производственной ситуации возникает отклонение по теме урока. Какое действие соответствует изученному материалу?',options:[c,'Сразу изменить несколько параметров одновременно.','Пропустить контроль результата.','Ориентироваться только на один случайный лист.'],correct:[0],explanation:'Этот подход непосредственно следует из материала урока.'},
      {type:'single',q:'Какой принцип нужно сохранить при работе по теме урока?',options:[d,'Игнорировать эталон и контроль.','Переносить настройки без проверки.','Считать один хороший лист достаточным.'],correct:[0],explanation:'Ответ сформулирован в материале урока.'}
    ];
  }
  function upgradeMachineCourse(id){
    const c=courses.find(x=>x.id===id);
    if(!c || !Array.isArray(c.lessons)) return;
    c.lessons.forEach(l=>{ l.questions=makeLessonQuestions(l); });
  }
  // These two equipment courses had overly generic one-question checks.
  upgradeMachineCourse('xl106');
  upgradeMachineCourse('roland');

  // Content QA for every lesson: if an existing correct option cannot be found in the
  // lesson text, replace that individual check with a directly text-grounded question.
  courses.forEach(c=>{
    if(!Array.isArray(c.lessons)) return;
    c.lessons.forEach(l=>{
      if(!Array.isArray(l.questions)) return;
      const text=lessonText(l).toLowerCase();
      l.questions=l.questions.map(q=>{
        if(!q || !Array.isArray(q.options) || !Array.isArray(q.correct) || !q.options.length) return q;
        const bad=q.correct.some(i=>{const v=q.options[i]; return typeof v==='string' && !text.includes(v.toLowerCase().trim());});
        if(!bad) return q;
        const source=(Array.isArray(l.bullets)&&l.bullets[0]) || l.goal || l.intro || l.title;
        return {type:'single',q:'Что прямо следует из материала этого урока?',options:[source,'Игнорировать этот принцип.','Менять несколько условий без проверки.','Оценивать только скорость процесса.'],correct:[0],explanation:'Ответ находится непосредственно в изученном материале.'};
      });
    });
  });

  // Remove repeated hero photography from the introductory course. Unique local educational
  // visuals are preferable to showing the same external photo several times.
  const intro=courses.find(x=>x.id==='intro');
  if(intro && Array.isArray(intro.lessons)){
    const seen=new Set();
    intro.lessons.forEach((l,i)=>{
      if(!l.image) return;
      if(seen.has(l.image)){
        const fallback='assets/intro/'+String(i+1).padStart(2,'0')+'-'+['role','cycle','job','materials','machine','start','makeready','control','color','register','diagnosis','waste','shift','safety','development','assignment','route','plate','sheetpath','unit','ink','dampening','firstsheet','stability','measurement','visual','repeat','stop','workspace'][i]+'.svg';
        l.image=fallback; l.heroSource='';
      } else seen.add(l.image);
    });
  }
  window.PRINTSTYLE_COURSE_QA={version:'3.5',xl106Questions:3,rolandQuestions:3,answerGroundedQA:true,introDuplicateHeroFix:true};
})();
